export const malaysia=countries.find(c=>c.code==='MYS');
export const value=(c,s,mode)=>c[s]==null?null:mode==='gap'?c[s]-malaysia[s]:c[s];
export const format=n=>n==null?'Not available':String(n);
export const signed=n=>n==null?'Not available':n>0?'+'+n:String(n);
export function colour(n,mode){if(n==null)return '#dde2e5';if(mode==='gap')return n< -50?'#bd692a':n<0?'#edbc86':n===0?'#315ad8':n<50?'#7fc9c0':'#17776c';return n<400?'#d2e9eb':n<450?'#91c6cd':n<500?'#4b9fab':n<550?'#226e82':'#113e58';}
